USE banking_financial_management;
CREATE TABLE branches (branch_id INT PRIMARY KEY AUTO_INCREMENT, branch_code VARCHAR(20) UNIQUE NOT NULL, branch_name VARCHAR(100) NOT NULL, city VARCHAR(80) NOT NULL, state VARCHAR(80) NOT NULL);
CREATE TABLE customers (customer_id BIGINT PRIMARY KEY AUTO_INCREMENT, customer_number VARCHAR(30) UNIQUE NOT NULL, first_name VARCHAR(60) NOT NULL, last_name VARCHAR(60) NOT NULL, email VARCHAR(150) UNIQUE NOT NULL, phone VARCHAR(20), date_of_birth DATE NOT NULL, customer_since DATE NOT NULL, risk_level ENUM('LOW','MEDIUM','HIGH') DEFAULT 'LOW', branch_id INT, FOREIGN KEY (branch_id) REFERENCES branches(branch_id));
CREATE TABLE accounts (account_id BIGINT PRIMARY KEY AUTO_INCREMENT, account_number VARCHAR(30) UNIQUE NOT NULL, customer_id BIGINT NOT NULL, branch_id INT NOT NULL, account_type ENUM('SAVINGS','CURRENT','SALARY','BUSINESS') NOT NULL, opened_at DATE NOT NULL, status ENUM('ACTIVE','FROZEN','CLOSED') DEFAULT 'ACTIVE', current_balance DECIMAL(18,2) DEFAULT 0, FOREIGN KEY (customer_id) REFERENCES customers(customer_id), FOREIGN KEY (branch_id) REFERENCES branches(branch_id));
CREATE TABLE cards (card_id BIGINT PRIMARY KEY AUTO_INCREMENT, card_number VARCHAR(32) UNIQUE NOT NULL, customer_id BIGINT NOT NULL, account_id BIGINT NOT NULL, card_type ENUM('DEBIT','CREDIT') NOT NULL, issued_at DATE NOT NULL, credit_limit DECIMAL(18,2) DEFAULT 0, status ENUM('ACTIVE','BLOCKED','EXPIRED') DEFAULT 'ACTIVE', FOREIGN KEY (customer_id) REFERENCES customers(customer_id), FOREIGN KEY (account_id) REFERENCES accounts(account_id));
CREATE TABLE merchants (merchant_id BIGINT PRIMARY KEY AUTO_INCREMENT, merchant_name VARCHAR(150) NOT NULL, merchant_category VARCHAR(80) NOT NULL, city VARCHAR(80), risk_level ENUM('LOW','MEDIUM','HIGH') DEFAULT 'LOW');
CREATE TABLE transactions (transaction_id BIGINT PRIMARY KEY AUTO_INCREMENT, account_id BIGINT NOT NULL, transaction_type ENUM('CREDIT','DEBIT','TRANSFER','ATM','FEE') NOT NULL, amount DECIMAL(18,2) NOT NULL CHECK (amount > 0), transaction_time DATETIME NOT NULL, reference_code VARCHAR(50) UNIQUE NOT NULL, channel ENUM('BRANCH','ATM','ONLINE','MOBILE','POS') NOT NULL, merchant_id BIGINT NULL, status ENUM('PENDING','SUCCESS','FAILED','REVERSED') DEFAULT 'SUCCESS', FOREIGN KEY (account_id) REFERENCES accounts(account_id), FOREIGN KEY (merchant_id) REFERENCES merchants(merchant_id));
CREATE TABLE transfers (transfer_id BIGINT PRIMARY KEY AUTO_INCREMENT, transaction_id BIGINT NOT NULL, from_account_id BIGINT NOT NULL, to_account_id BIGINT NOT NULL, transfer_amount DECIMAL(18,2) NOT NULL CHECK (transfer_amount > 0), initiated_at DATETIME NOT NULL, status ENUM('PENDING','COMPLETED','FAILED','REVERSED') DEFAULT 'COMPLETED', FOREIGN KEY (transaction_id) REFERENCES transactions(transaction_id), FOREIGN KEY (from_account_id) REFERENCES accounts(account_id), FOREIGN KEY (to_account_id) REFERENCES accounts(account_id), CHECK (from_account_id <> to_account_id));
CREATE TABLE loans (loan_id BIGINT PRIMARY KEY AUTO_INCREMENT, customer_id BIGINT NOT NULL, account_id BIGINT NOT NULL, loan_type ENUM('PERSONAL','HOME','AUTO','BUSINESS','EDUCATION') NOT NULL, principal DECIMAL(18,2) NOT NULL, interest_rate DECIMAL(6,3) NOT NULL, tenure_months INT NOT NULL, start_date DATE NOT NULL, status ENUM('ACTIVE','CLOSED','DEFAULTED') DEFAULT 'ACTIVE', FOREIGN KEY (customer_id) REFERENCES customers(customer_id), FOREIGN KEY (account_id) REFERENCES accounts(account_id));
CREATE TABLE loan_payments (payment_id BIGINT PRIMARY KEY AUTO_INCREMENT, loan_id BIGINT NOT NULL, due_date DATE NOT NULL, paid_date DATE NULL, amount_due DECIMAL(18,2) NOT NULL, amount_paid DECIMAL(18,2) DEFAULT 0, status ENUM('DUE','PAID','LATE','MISSED') DEFAULT 'DUE', FOREIGN KEY (loan_id) REFERENCES loans(loan_id));
CREATE TABLE fraud_events (fraud_event_id BIGINT PRIMARY KEY AUTO_INCREMENT, transaction_id BIGINT NOT NULL, detected_at DATETIME NOT NULL, fraud_type VARCHAR(100) NOT NULL, risk_score DECIMAL(5,2) NOT NULL, action_taken ENUM('REVIEW','BLOCK','ALLOW') NOT NULL, FOREIGN KEY (transaction_id) REFERENCES transactions(transaction_id));
CREATE TABLE disputes (dispute_id BIGINT PRIMARY KEY AUTO_INCREMENT, transaction_id BIGINT NOT NULL, opened_at DATETIME NOT NULL, reason VARCHAR(200) NOT NULL, disputed_amount DECIMAL(18,2) NOT NULL, status ENUM('OPEN','WON','LOST','REFUNDED') DEFAULT 'OPEN', FOREIGN KEY (transaction_id) REFERENCES transactions(transaction_id));
CREATE TABLE settlements (settlement_id BIGINT PRIMARY KEY AUTO_INCREMENT, transaction_id BIGINT NOT NULL, settled_at DATETIME NULL, settlement_amount DECIMAL(18,2) NOT NULL, status ENUM('PENDING','SETTLED','FAILED') DEFAULT 'PENDING', FOREIGN KEY (transaction_id) REFERENCES transactions(transaction_id));
